package com.mfix.pos;

import android.os.Bundle;
import android.view.View;
import android.view.ViewGroup;
import android.webkit.WebView;

/** Adds explicit multi-IMEI/serial inventory management on top of the live inventory chain. */
public class SerialInventoryActivePatchActivity extends GranularPermissionsActivePatchActivity {
    private static final String PATCH =
        "(function(){if(window.__mfixSerialInventory)return;window.__mfixSerialInventory=true;"+
        "function esc(s){return String(s==null?'':s).replace(/[&<>\\\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\\\"':'&quot;',\"'\":'&#39;'}[c];});}"+
        "function save(){try{if(typeof saveKey==='function'){saveKey('products',STATE.products);saveKey('misc',{returns:STATE.returns,shifts:STATE.shifts,giftCards:STATE.giftCards,preorders:STATE.preorders,auditLog:STATE.auditLog,inventoryHistory:STATE.inventoryHistory});}}catch(e){console.error(e);}}"+
        "function values(p){var a=[];if(Array.isArray(p.imeis))a=a.concat(p.imeis.map(function(x){return String(x&&typeof x==='object'?x.value||x.imei||x.serial||'':x).trim();}));if(Array.isArray(p.serials))a=a.concat(p.serials.map(function(x){return String(x&&typeof x==='object'?x.value||x.imei||x.serial||'':x).trim();}));if(!a.length&&p.imei)a.push(String(p.imei).trim());if(!a.length&&p.serial)a.push(String(p.serial).trim());return a.filter(Boolean);}"+
        "function install(){var v=document.getElementById('view-inventory');if(!v)return false;if(document.getElementById('mfixSerialCard'))return true;var b=document.createElement('div');b.id='mfixSerialCard';b.className='card';b.style.marginBottom='12px';b.innerHTML='<div class=\"section-title\">📱 IMEI / מספר סידורי</div><div class=\"muted\" style=\"font-size:12px;margin-bottom:10px\">ניהול יחידות לפי מספר. כל שורה מייצגת יחידה אחת.</div><div style=\"display:flex;gap:8px;flex-wrap:wrap\"><input id=\"mfixSerialSearch\" class=\"input\" style=\"max-width:300px\" placeholder=\"חיפוש מוצר / IMEI / סידורי\"></div><div id=\"mfixSerialRows\" style=\"margin-top:10px\"></div>';v.insertBefore(b,v.firstChild);function draw(q){q=String(q||'').toLowerCase();var ps=Array.isArray(STATE.products)?STATE.products:[];var rows=ps.filter(function(p){var a=values(p);return !q||String(p.name||'').toLowerCase().indexOf(q)>=0||String(p.sku||'').toLowerCase().indexOf(q)>=0||a.some(function(x){return x.toLowerCase().indexOf(q)>=0;});}).filter(function(p){return p.trackSerial||Array.isArray(p.imeis)||Array.isArray(p.serials)||p.imei||p.serial;}).slice(0,80);document.getElementById('mfixSerialRows').innerHTML=rows.length?rows.map(function(p){var a=values(p);return '<div class=\"card\" style=\"background:var(--gray-50);margin-bottom:8px\"><b>'+esc(p.name||p.sku||p.id)+'</b><div class=\"muted\" style=\"font-size:11px;margin:3px 0 8px\">מלאי: '+a.length+' · '+(p.trackSerial?'מעקב פעיל':'')+'</div><textarea class=\"input\" data-serial-text=\"'+esc(p.id)+'\" rows=\"4\" placeholder=\"IMEI / מספר סידורי — אחד בכל שורה\">'+esc(a.join('\\n'))+'</textarea><div style=\"margin-top:7px\"><button type=\"button\" class=\"btn btn-primary\" data-serial-save=\"'+esc(p.id)+'\">💾 שמור יחידות</button></div></div>';}).join(''):'<div class=\"empty-state\">אין מוצרים עם מעקב IMEI/סידורי. הפעילו trackSerial או הוסיפו יחידה דרך עריכת המוצר.</div>';document.querySelectorAll('[data-serial-save]').forEach(function(btn){btn.onclick=function(){var id=btn.getAttribute('data-serial-save'),p=ps.find(function(x){return String(x.id)===String(id);}),ta=document.querySelector('[data-serial-text=\"'+CSS.escape(id)+'\"]');if(!p||!ta)return;var before=Number(p.stock||0),a=String(ta.value||'').split(/\\r?\\n/).map(function(x){return x.trim();}).filter(Boolean),seen={};for(var i=0;i<a.length;i++){if(seen[a[i]]){toast('אותו IMEI/מספר סידורי מופיע יותר מפעם אחת','err');return;}seen[a[i]]=true;}p.trackSerial=true;p.imeis=a.map(function(x){return {value:x,status:'available'};});p.serials=[];p.imei=a.length===1?a[0]:'';p.serial=a.length===1?a[0]:'';p.stock=a.length;if(!Array.isArray(STATE.inventoryHistory))STATE.inventoryHistory=[];if(before!==p.stock)STATE.inventoryHistory.unshift({id:'invh_'+Date.now(),productId:p.id,type:p.stock>before?'adjust_in':'adjust_out',qty:Math.abs(p.stock-before),before:before,after:p.stock,serials:a,reason:'עדכון IMEI/סידורי',at:new Date().toISOString()});save();toast('יחידות IMEI/סידורי נשמרו','ok');draw(document.getElementById('mfixSerialSearch').value);};});}document.getElementById('mfixSerialSearch').oninput=function(){draw(this.value);};draw('');return true;}var n=0,t=setInterval(function(){if(install()||++n>=30)clearInterval(t);},600);console.log('[MFIX] serial inventory management active');})();";

    @Override protected void onCreate(Bundle savedInstanceState){
        super.onCreate(savedInstanceState);
        View root=((ViewGroup)findViewById(android.R.id.content)).getChildAt(0);
        if(root instanceof WebView)((WebView)root).postDelayed(()->((WebView)root).evaluateJavascript(PATCH,null),15500);
    }
}
